WITH not_flagged AS (SELECT s.* FROM suppliers s WHERE NOT EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.product_name IS NULL)) SELECT city, CASE WHEN rating >= 4.6 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, COUNT(*) FILTER (WHERE country = 'DE') AS de_rows, SUM(CASE WHEN city = 'Singapore' THEN rating ELSE 0 END) AS singapore_rating, STDDEV_SAMP(rating) AS rating_stddev, SUM(CASE WHEN country = 'UK' THEN rating ELSE 0 END) AS uk_rating FROM not_flagged GROUP BY city, CASE WHEN rating >= 4.6 THEN 'HIGH' ELSE 'LOW' END;
